function transform(event, ctx) {
  ctx.log('start', event.offset);
  if (event.offset === 1) {
    throw new Error('Event ' + event.offset + ' has no items');
  }
  if (event.offset === 2) {
    return 42;
  }
  if (event.offset === 3) {
    return ctx.formatDate('not a date', 'date');
  }
  return event.value.order.items;
}
